// استخراج نص الاستجابة من GigaChat
const responseText = $input.first().json.response || $input.first().json.content || JSON.stringify($input.first().json);

// إزالة علامات ```json و ```
let cleanText = responseText
  .replace(/```json\s*/g, '')
  .replace(/```\s*/g, '')
  .trim();

// محاولة تحليل JSON
let parsed;
try {
  parsed = JSON.parse(cleanText);
} catch (e) {
  // إذا فشل التحليل، حاول استخراج أول { ... } صالح
  const match = cleanText.match(/\{[\s\S]*\}/);
  if (match) {
    try {
      parsed = JSON.parse(match[0]);
    } catch (e2) {
      return [{ json: { error: 'JSON parsing failed', raw: cleanText } }];
    }
  } else {
    return [{ json: { error: 'No JSON found', raw: cleanText } }];
  }
}

// إرجاع النتيجة
return [{ json: parsed }];

const data = $input.first().json;
const scenes = data["مشاهد الحلقة"] || data.scenes || [];

if (!Array.isArray(scenes) || scenes.length === 0) {
  return [{ json: { error: 'No scenes found', data } }];
}

return scenes.map((scene, index) => ({
  json: {
    sceneNumber: scene["رقم المشهد"] || index + 1,
    visual: scene["وصف البصري"] || scene["visual"] || "",
    dialogue: scene["الحوار والتعليق الصوتي"] || scene["dialogue"] || "",
    duration: scene["مدة المقترح"] || scene["duration"] || "10 ثواني",
    title: data["عنوان الحلقة"] || "",
    characters: data["الشخصيات"] || [],
    place: data["المكان"] || ""
  }
}));

