const data = $input.first().json;

// محاولة إيجاد رابط الفيديو من حقول مختلفة
let videoUrl = null;

if (data.downloads && data.downloads.url) {
  videoUrl = data.downloads.url;
} else if (data.download && data.download.url) {
  videoUrl = data.download.url;
} else if (data.url) {
  videoUrl = data.url;
}

return [{
  json: {
    videoUrl: videoUrl,
    status: data.status,
    id: data.id,
    width: data.width,
    height: data.height,
    endSeconds: data.end_seconds,
    creditsCharged: data.credits_charged,
    rawData: data
  }
}];
